public class RB1 {
    public static class Msg extends ListResourceBundle {
        protected Object[][] getContents() { return new Object[][]{{"hi", "Hello"}, {"bye", "Goodbye"}}; }
    }
    public static class Msg_pl extends ListResourceBundle {
        protected Object[][] getContents() { return new Object[][]{{"hi", "Cześć"}}; }
    }
    public static void main(String[] args) {
        ResourceBundle rb = ResourceBundle.getBundle("RB1$Msg", Locale.of("pl", "PL"));
        System.out.println(rb.getString("hi") + " " + rb.getString("bye"));
    }
}

public class RB2 {
    public static class Msg extends ListResourceBundle {
        protected Object[][] getContents() { return new Object[][]{{"hi", "Hello"}}; }
    }
    public static void main(String[] args) {
        ResourceBundle rb = ResourceBundle.getBundle("RB2$Msg", Locale.JAPAN);
        System.out.println(rb.getString("hi") + " " + rb.containsKey("x") + " " + rb.keySet());
    }
}

